-- VinFast demo CMS schema (Cloudflare D1 / SQLite)
--
-- Run this file once in the D1 console, or with:
--   npx wrangler d1 execute <database-name> --remote --file=backend/schema.sql
--
-- All statements are idempotent. Seed data lives in backend/seed/*.sql and is
-- generated by `npm run seed:build`.

CREATE TABLE IF NOT EXISTS products (
  slug TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  type TEXT NOT NULL CHECK (type IN ('car', 'motorbike')),
  category TEXT NOT NULL,
  tagline TEXT NOT NULL DEFAULT '',
  price INTEGER NOT NULL DEFAULT 0,
  price_note TEXT NOT NULL DEFAULT '',
  badge TEXT NOT NULL DEFAULT '',
  featured INTEGER NOT NULL DEFAULT 0 CHECK (featured IN (0, 1)),
  sort_order INTEGER NOT NULL DEFAULT 0,
  description TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'published'
    CHECK (status IN ('published', 'draft', 'archived')),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS product_quick_specs (
  product_slug TEXT NOT NULL REFERENCES products(slug) ON DELETE CASCADE,
  sort_order INTEGER NOT NULL,
  label TEXT NOT NULL DEFAULT '',
  value TEXT NOT NULL DEFAULT '',
  PRIMARY KEY (product_slug, sort_order)
);

CREATE TABLE IF NOT EXISTS product_spec_groups (
  product_slug TEXT NOT NULL REFERENCES products(slug) ON DELETE CASCADE,
  group_index INTEGER NOT NULL,
  group_name TEXT NOT NULL DEFAULT '',
  PRIMARY KEY (product_slug, group_index)
);

CREATE TABLE IF NOT EXISTS product_spec_items (
  product_slug TEXT NOT NULL,
  group_index INTEGER NOT NULL,
  item_index INTEGER NOT NULL,
  label TEXT NOT NULL DEFAULT '',
  value TEXT NOT NULL DEFAULT '',
  PRIMARY KEY (product_slug, group_index, item_index),
  FOREIGN KEY (product_slug, group_index)
    REFERENCES product_spec_groups(product_slug, group_index)
    ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS product_images (
  product_slug TEXT NOT NULL REFERENCES products(slug) ON DELETE CASCADE,
  sort_order INTEGER NOT NULL,
  url TEXT NOT NULL,
  alt TEXT NOT NULL DEFAULT '',
  PRIMARY KEY (product_slug, sort_order)
);

CREATE TABLE IF NOT EXISTS product_colors (
  product_slug TEXT NOT NULL REFERENCES products(slug) ON DELETE CASCADE,
  sort_order INTEGER NOT NULL,
  name TEXT NOT NULL DEFAULT '',
  hex TEXT NOT NULL DEFAULT '',
  image TEXT NOT NULL DEFAULT '',
  PRIMARY KEY (product_slug, sort_order)
);

CREATE TABLE IF NOT EXISTS product_offers (
  product_slug TEXT NOT NULL REFERENCES products(slug) ON DELETE CASCADE,
  sort_order INTEGER NOT NULL,
  title TEXT NOT NULL DEFAULT '',
  description TEXT NOT NULL DEFAULT '',
  valid_until TEXT NOT NULL DEFAULT '',
  PRIMARY KEY (product_slug, sort_order)
);

CREATE TABLE IF NOT EXISTS product_highlights (
  product_slug TEXT NOT NULL REFERENCES products(slug) ON DELETE CASCADE,
  sort_order INTEGER NOT NULL,
  title TEXT NOT NULL DEFAULT '',
  text TEXT NOT NULL DEFAULT '',
  PRIMARY KEY (product_slug, sort_order)
);

CREATE TABLE IF NOT EXISTS sale_items (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS sale_programs (
  product_id TEXT PRIMARY KEY REFERENCES products(slug) ON DELETE CASCADE,
  enabled INTEGER NOT NULL DEFAULT 0 CHECK (enabled IN (0, 1)),
  percent_discount INTEGER NOT NULL DEFAULT 0,
  flat_discount INTEGER NOT NULL DEFAULT 0,
  updated_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS sale_program_items (
  product_id TEXT NOT NULL REFERENCES sale_programs(product_id) ON DELETE CASCADE,
  sort_order INTEGER NOT NULL,
  item_id TEXT NOT NULL REFERENCES sale_items(id),
  note TEXT NOT NULL DEFAULT '',
  PRIMARY KEY (product_id, sort_order)
);

CREATE TABLE IF NOT EXISTS sale_program_details (
  product_id TEXT NOT NULL REFERENCES sale_programs(product_id) ON DELETE CASCADE,
  sort_order INTEGER NOT NULL,
  title TEXT NOT NULL DEFAULT '',
  text TEXT NOT NULL DEFAULT '',
  PRIMARY KEY (product_id, sort_order)
);

CREATE TABLE IF NOT EXISTS articles (
  slug TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  excerpt TEXT NOT NULL DEFAULT '',
  category TEXT NOT NULL DEFAULT '',
  cover_image TEXT NOT NULL DEFAULT '',
  content_html TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'draft'
    CHECK (status IN ('draft', 'published', 'archived')),
  author TEXT NOT NULL DEFAULT '',
  seo_title TEXT NOT NULL DEFAULT '',
  seo_description TEXT NOT NULL DEFAULT '',
  published_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS media (
  id TEXT PRIMARY KEY,
  r2_key TEXT NOT NULL UNIQUE,
  url TEXT NOT NULL,
  filename TEXT NOT NULL DEFAULT '',
  mime_type TEXT NOT NULL,
  size_bytes INTEGER NOT NULL DEFAULT 0,
  alt TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_products_type_status
  ON products (type, status, sort_order);

CREATE INDEX IF NOT EXISTS idx_products_featured
  ON products (featured);

CREATE INDEX IF NOT EXISTS idx_sale_program_items_item
  ON sale_program_items (item_id);

CREATE INDEX IF NOT EXISTS idx_articles_status_published
  ON articles (status, published_at DESC);

CREATE INDEX IF NOT EXISTS idx_articles_category
  ON articles (category);

CREATE INDEX IF NOT EXISTS idx_media_created
  ON media (created_at DESC);
